style.css:
@-moz-document domain("pinterest.com"), domain("www.pinterest.com") {
@font-face {
    font-family: 'Hachi Maru Pop';
    font-style: normal;
    font-weight: 400;
    src: url('https://fonts.gstatic.com/s/hachimaru/v15/yYLx0hXQEFjGG7QxXzEwrQ.woff2') format('woff2');
  }

  body {
    background-color: #FFF8E7 !important; /* giallo crema */
    color: #4B3B2B !important;
    font-family: 'Hachi Maru Pop', cursive !important;
  }

  /* Cambia il colore di sfondo delle cards dei pin, ma solo le card, non immagini */
  .GrowthUnauthPinImage, .GrowthUnauthPinImage img {
    background-color: transparent !important; /* niente sfondo che copre immagini */
  }

  /* Aggiustiamo le card contenitori: prendiamo solo le card e box di testo */
  .GrowthUnauthPinImageContainer, 
  .pinWrapper, 
  .pinWrapper > div {
    background-color: #FFE4E9 !important; /* rosa pastello leggero per contenitori */
    border-radius: 12px !important;
  }

  /* Titoli e testi */
  h1, h2, h3, h4, h5, h6 {
    color: #4B3B2B !important;
    font-family: 'Hachi Maru Pop', cursive !important;
  }

  /* Pulsanti */
  button, .Button, .btn {
    background-color: #FADADD !important;
    color: #4B3B2B !important;
    border-radius: 8px !important;
    font-family: 'Hachi Maru Pop', cursive !important;
  }

  /* Link */
  a {
    color: #E8A87C !important;
    font-family: 'Hachi Maru Pop', cursive !important;
  }
}
